MAP
    NAME "SS_MAP_DREN_POZOS_DRENAJE"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_pozos_drenaje.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_POZOS_DRENAJE"
            PROJECTION
            'init=epsg:32614'
        END #PROJECION
        METADATA
            'ows_title' 'Pozos'
            'gml_featureid' 'gid'
            'gml_include_items' 'all'
            'wfs_enable_request' '*'
        END #METADATA
        DEBUG 2
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from pozossec using unique gid using srid=32614"
        TYPE POINT
        TOLERANCE 6
        TOLERANCEUNITS PIXELS
        MAXSCALE 15000
        CLASSITEM "tipo"
        CLASS
            NAME "Pozos de visita"
            EXPRESSION "1"
            STYLE
                SYMBOL "aguaK"
                SIZE 10
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #STYLE
        END #CLASS
        CLASS
            NAME "Pozo cabecero"
            EXPRESSION "2"
            STYLE
                SYMBOL "aguaL"
                SIZE 10
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #STYLE
        END #CLASS
        CLASS
            NAME "Caida libre"
            EXPRESSION "3"
            STYLE
                SYMBOL "aguaM"
                SIZE 10
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #STYLE
        END #CLASS
        CLASS
            NAME "Caida adosada"
            EXPRESSION "4"
            STYLE
                SYMBOL "aguaN"
                SIZE 10
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #STYLE
        END #CLASS
        CLASS
            NAME "Otras caidas"
            EXPRESSION "5"
            STYLE
                SYMBOL "aguaO"
                SIZE 16
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP